    else:
        date_ok = day_ok or weekday_ok
    return when.minute in c["minute"] and when.hour in c["hour"] and when.month in c["month"] and date_ok

def next_run(expression, after):
    t = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    while not matches(expression, t):
        t += timedelta(minutes=1)
    return t


print(next_run("30 2 * * 1-5", datetime(2025, 3, 7, 2, 30)))
